CREATE TABLE IF NOT EXISTS ai_policies(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,agent_mode TEXT NOT NULL DEFAULT 'disabled' CHECK(agent_mode IN ('disabled','shadow','copilot','assisted','autonomous')),allowed_tools JSONB NOT NULL DEFAULT '[]'::jsonb,approval_required JSONB NOT NULL DEFAULT '["send_message","generate_quote","delete"]'::jsonb,daily_budget_micros BIGINT NOT NULL DEFAULT 0,updated_by UUID REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant_id));